#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::string line;
    std::istringstream is(markdown);

    while (std::getline(is, line)) {
        html += line + "\n";
    }

    return html;
}

int main() {
    std::string markdown = "# Heading\n\nThis is a paragraph.\n\nThis is a list";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

